//go:build windows

package main

// Rhythm quiz (Quiz menu): ten 10-second strips generated by the simulator,
// each with four answers (the distractors come mostly from similar rhythms).
// After answering, the correct rhythm and a teaching point are shown; the
// score is kept in the header. Calipers work on the quiz strips as on any
// strip.

import (
	"fmt"
	"math/rand"
	"time"
	"unsafe"
)

// quizState is the state of a quiz in its strip window.
type quizState struct {
	n, total, score int
	item            quizItem
	choices         []string
	answered        bool
	rng             *rand.Rand
	radios          [4]uintptr
	submit, next    uintptr
	clearCal        uintptr
	feedback        uintptr
}

const (
	quizLength     = 10
	ctlQuizRadio   = 801 // ..804
	ctlQuizSubmit  = 810
	ctlQuizNext    = 811
	ctlQuizClear   = 813
	bsAutoRadio    = 0x0009
	quizFeedbackID = 812
)

// openQuiz starts a new 10-question rhythm quiz.
func openQuiz() {
	q := &quizState{total: quizLength, rng: rand.New(rand.NewSource(time.Now().UnixNano()))}
	s := &Strip{bed: 0, quiz: q}
	quizQuestion(s)
	showStrip(s, "Rhythm Quiz")
}

// quizQuestion generates the next strip and its four choices.
func quizQuestion(s *Strip) {
	q := s.quiz
	r := q.rng
	q.n++
	q.answered = false
	q.item = quizPool[r.Intn(len(quizPool))]
	s.data, s.paces, s.lead, _ = quizStrip(r, q.item)
	s.cal = calipers{}
	// choices: the answer, two from similar rhythms, one from anywhere
	pick := []string{q.item.name}
	used := map[string]bool{q.item.name: true}
	var same, other []string
	for _, it := range quizPool {
		if used[it.name] {
			continue
		}
		if it.group == q.item.group {
			same = append(same, it.name)
		} else {
			other = append(other, it.name)
		}
	}
	r.Shuffle(len(same), func(i, j int) { same[i], same[j] = same[j], same[i] })
	r.Shuffle(len(other), func(i, j int) { other[i], other[j] = other[j], other[i] })
	for _, n := range same {
		if len(pick) < 3 {
			pick, used[n] = append(pick, n), true
		}
	}
	for _, n := range other {
		if len(pick) < 4 && !used[n] {
			pick, used[n] = append(pick, n), true
		}
	}
	r.Shuffle(len(pick), func(i, j int) { pick[i], pick[j] = pick[j], pick[i] })
	q.choices = pick
	if q.radios[0] != 0 {
		quizRefreshControls(s)
	}
}

// quizButtons creates the answer panel.
func quizButtons(hwnd uintptr, s *Strip) {
	q := s.quiz
	ctlParent = hwnd
	uiFont = font(S(15), false, "Segoe UI")
	for i := range q.radios {
		style := uint32(WS_TABSTOP | bsAutoRadio)
		if i == 0 {
			style |= 0x00020000 // WS_GROUP
		}
		q.radios[i] = ctl("BUTTON", "", style, 0, 0, 10, 10, ctlQuizRadio+i)
	}
	q.submit = ctl("BUTTON", "Check Answer", WS_TABSTOP|BS_DEFPUSHBUTTON, 0, 0, 10, 10, ctlQuizSubmit)
	q.next = ctl("BUTTON", "Next Rhythm", WS_TABSTOP, 0, 0, 10, 10, ctlQuizNext)
	q.clearCal = ctl("BUTTON", "Clear Calipers", WS_TABSTOP, 0, 0, 10, 10, ctlQuizClear)
	q.feedback = ctl("STATIC", "", 0, 0, 0, 10, 10, quizFeedbackID)
	var rc RECT
	call(pGetClientRect, hwnd, uintptr(unsafe.Pointer(&rc)))
	layoutQuiz(s, rc.Right, rc.Bottom)
	quizRefreshControls(s)
}

func layoutQuiz(s *Strip, w, h int32) {
	q := s.quiz
	if q.submit == 0 {
		return
	}
	mv := func(hw uintptr, x, y, cw, ch int32) {
		call(pSetWindowPos, hw, 0, uintptr(x), uintptr(y), uintptr(cw), uintptr(ch), 0x0004)
	}
	m := S(16)
	y0 := h - stripPanelH() + S(6)
	half := (w*55/100 - m) / 2
	for i, rb := range q.radios {
		mv(rb, m+half*int32(i%2), y0+S(30)*int32(i/2), half-S(8), S(26))
	}
	mv(q.submit, m, y0+S(70), S(150), S(30))
	mv(q.next, m+S(160), y0+S(70), S(150), S(30))
	mv(q.clearCal, m+S(320), y0+S(70), S(150), S(30))
	fx := w * 57 / 100
	mv(q.feedback, fx, y0, w-m-fx, stripPanelH()-S(14))
}

// quizRefreshControls loads the choices and resets the answer state.
func quizRefreshControls(s *Strip) {
	q := s.quiz
	for i, rb := range q.radios {
		txt := ""
		if i < len(q.choices) {
			txt = q.choices[i]
		}
		call(pSetWindowTextW, rb, uintptr(unsafe.Pointer(wstr(txt))))
		call(pSendMessageW, rb, BM_SETCHECK, 0, 0)
		enable(rb, true)
	}
	enable(q.submit, true)
	call(pSetWindowTextW, q.next, uintptr(unsafe.Pointer(wstr("Next Rhythm"))))
	enable(q.next, false)
	call(pSetWindowTextW, q.feedback, uintptr(unsafe.Pointer(wstr("Choose the rhythm, then Check Answer. Calipers work on the strip."))))
}

// quizCommand handles the quiz panel buttons.
func quizCommand(hwnd uintptr, s *Strip, id int) bool {
	q := s.quiz
	switch {
	case id >= ctlQuizRadio && id < ctlQuizRadio+4:
		return true
	case id == ctlQuizSubmit && !q.answered:
		sel := -1
		for i, rb := range q.radios {
			if call(pSendMessageW, rb, BM_GETCHECK, 0, 0) == 1 {
				sel = i
			}
		}
		if sel < 0 {
			call(pSetWindowTextW, q.feedback, uintptr(unsafe.Pointer(wstr("Select one of the four rhythms first."))))
			return true
		}
		q.answered = true
		var msg string
		if q.choices[sel] == q.item.name {
			q.score++
			msg = "✔ Correct: " + q.item.name + ".\r\n" + q.item.why
		} else {
			msg = "✘ Not quite - this is " + q.item.name + ".\r\n" + q.item.why
		}
		for _, rb := range q.radios {
			enable(rb, false)
		}
		enable(q.submit, false)
		enable(q.next, true)
		if q.n >= q.total {
			msg += fmt.Sprintf("\r\n\r\nQuiz complete: %d of %d correct (%d%%).", q.score, q.total, q.score*100/q.total)
			call(pSetWindowTextW, q.next, uintptr(unsafe.Pointer(wstr("New Quiz"))))
		}
		call(pSetWindowTextW, q.feedback, uintptr(unsafe.Pointer(wstr(msg))))
	case id == ctlQuizClear:
		s.cal.tOn, s.cal.vOn = false, false
	case id == ctlQuizNext && q.answered:
		if q.n >= q.total { // start over
			q.n, q.score = 0, 0
		}
		quizQuestion(s)
	default:
		return true
	}
	call(pInvalidateRect, hwnd, 0, 0)
	return true
}

// quizHeader draws the quiz title line and score.
func quizHeader(dc uintptr, s *Strip, w int32) {
	q := s.quiz
	m := S(16)
	text(dc, fmt.Sprintf("Rhythm Quiz  –  Question %d of %d", q.n, q.total), m, S(6), w-m, S(30), rgb(0, 0, 0), font(S(19), true, "Segoe UI"), DT_SINGLELINE)
	answered := q.n - 1
	if q.answered {
		answered = q.n
	}
	text(dc, fmt.Sprintf("Score: %d / %d", q.score, answered), w/2, S(6), w-m, S(30), rgb(0, 90, 0), font(S(18), true, "Segoe UI"), DT_SINGLELINE|DT_RIGHT)
	text(dc, "Lead "+s.lead+"     25 mm/s     10 mm/mV     10 seconds", m, S(30), w-m, S(52), rgb(40, 40, 40), font(S(14), false, "Segoe UI"), DT_SINGLELINE)
}
